const (
	programName = "test_dns_parser"
	objName     = "dns_parser_test.o"

	DNSParserSuccess = 0
	DNSParserSkip    = 1
)

var verifierLogs = flag.Bool("verlogs", false, "Write the full verifier logs in the ./verifier.log file")
var pcapFile = flag.String("pcap", "", "Pcap file to load for the DNS parser test")

func parseIPs(ips ...string) []netip.Addr {
	netIPs := []netip.Addr{}
	for _, ip := range ips {
		netIPs = append(netIPs, netip.MustParseAddr(ip))
	}
	return netIPs
}

func loadDNSTestCollection(t *testing.T) *ebpf.Collection {
	if !utils.SupportDNSParser() {
		t.Skip()
	}

	// load test program
	collSpec, err := ebpf.LoadCollectionSpec(filepath.Join("../../bpf/tests/objs", objName))
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			t.Fatalf("please run 'make tetragon-bpf-test' to compile the BPF test program: %s", err)
		}
		t.Fatal(err)
	}

	// Resizing map (to an overkill size because it's LRU_HASH)
	collSpec.Maps[DomainToIDMapName].MaxEntries = 1024
	collSpec.Maps[IDToDomainMapName].MaxEntries = 1024
	collSpec.Maps[RequestIDMapName].MaxEntries = 1024
	// Normally, the max entries is DNS_ERR_MAX, but the testing harness uses more errors
	collSpec.Maps[ErrorMapName].MaxEntries = 128

	collOpts := ebpf.CollectionOptions{}
	if verifierLogs != nil && *verifierLogs {
		collOpts.Programs = ebpf.ProgramOptions{
			LogLevel: ebpf.LogLevelInstruction,
		}
	}
	coll, err := ebpf.NewCollectionWithOptions(collSpec, collOpts)
	if err != nil {
		var ve *ebpf.VerifierError
		if errors.As(err, &ve) {
			t.Fatalf("verifier error: %+v\n", ve)
		}
		t.Fatal(err)
	}
	t.Cleanup(func() {
		coll.Close()
	})

	prog, ok := coll.Programs[programName]
	if !ok {
		t.Fatalf("%s not found", programName)
	}

	if verifierLogs != nil && *verifierLogs {
		logFile, err := os.Create("verifier.log")
		if err != nil {
			t.Fatal(err)
		}

		_, err = logFile.WriteString(prog.VerifierLog)
		if err != nil {
			t.Fatal(err)
		}
		logFile.Close()
	}

	// Direct packet access with BPF_PROG_TYPE_CGROUP_SKB in BPF_PROG_TEST_RUN needs
	// https://lore.kernel.org/r/20241125152603.375898-1-mahe.tardy@gmail.com
	if v := "6.13.0"; !kernels.MinKernelVersion(v) {
		t.Skipf("DNS parser test prog loads but cannot run: minimum kernel version (%v) not met, skipping", v)
	}

	return coll
}

type testQuery struct {
	name        string
	request     []byte
	response    []byte
	wantDomain  string
	wantIPs     []netip.Addr
	wantSkip    bool
	wantRespErr bool
	wantReqErr  bool
}

func RunStandardQueryResponse(t *testing.T, tq testQuery, prog *ebpf.Program, ipToDomainMap IPToDomainMap, errMap ErrorMap) {
	runStandardQuery(t, tq, prog, ipToDomainMap, errMap, false)
}

func RunStandardQueryRequest(t *testing.T, tq testQuery, prog *ebpf.Program, ipToDomainMap IPToDomainMap, errMap ErrorMap) {
	runStandardQuery(t, tq, prog, ipToDomainMap, errMap, true)
}

func runStandardQuery(t *testing.T, tq testQuery, prog *ebpf.Program, ipToDomainMap IPToDomainMap, errMap ErrorMap, request bool) {
	defer func() {
		err := ipToDomainMap.Clear()
		if err != nil {
			t.Error(err)
		}
		err = errMap.Clear()
		if err != nil {
			t.Error(err)
		}
	}()

	var code uint32
	var err error
	if request {
		code, err = prog.Run(&ebpf.RunOptions{
			Data: tq.request,
		})
	} else {
		code, err = prog.Run(&ebpf.RunOptions{
			Data: tq.response,
		})
	}
	if err != nil {
		t.Fatal(err)
	}

	// The test harness returns skip in case of error, this is only an
	// implementation detail of the harness because it can only return [0, 3]
	if request && tq.wantReqErr || !request && tq.wantRespErr {
		tq.wantSkip = true
	}

	// the return code is 0 for success and 1 for skip, for skip the error can be set
	if code != DNSParserSuccess && code != DNSParserSkip {
		t.Errorf("unexpected, returned code is != from %d and %d: %d", DNSParserSuccess, DNSParserSkip, code)
	}
	if code == DNSParserSuccess && tq.wantSkip {
		t.Errorf("wanted skip, returned code is != %d: %d", DNSParserSkip, code)
	}
	if code == DNSParserSkip {
		if !tq.wantSkip {
			t.Errorf("wanted success, returned code is != %d: %d", DNSParserSuccess, code)
		} else {
			t.Logf("got expected skip")
		}
	}

	errValue, err := errMap.ReadUnique()
	if err != nil {
		t.Fatal(err)
	}
	wantError := tq.wantRespErr
	if request {
		wantError = tq.wantReqErr
	}
	if errValue != 0 {
		if wantError {
			t.Logf("got expected error %d %s", errValue, Errors[errValue])
			return // success
		}
		t.Errorf("got error %d %s and want no error", errValue, Errors[errValue])
	} else {
		if wantError {
			t.Errorf("got no error and want error")
		}
	}

	if request {
		return
	}

	wantIPMaps := map[netip.Addr]string{}
	for _, ip := range tq.wantIPs {
		wantIPMaps[ip] = tq.wantDomain
	}

	actualIP, err := ipToDomainMap.Values(DefaultInnerMapID)
	if err != nil {
		t.Fatalf("failed to retrieve values out of IP map: %s", err)
	}

	if len(actualIP) != len(wantIPMaps) {
		t.Errorf("len(got) %d != len(want) %d", len(actualIP), len(wantIPMaps))
		t.FailNow()
	}

	if !maps.Equal(actualIP, wantIPMaps) {
		t.Errorf("got %v, expected %v", actualIP, wantIPMaps)
		if len(actualIP) > 0 && len(wantIPMaps) > 0 {
			actualValues := slices.Collect(maps.Values(actualIP))
			wantValues := slices.Collect(maps.Values(wantIPMaps))
			t.Errorf("domain: got %v, expected %v", []byte(actualValues[0]), []byte(wantValues[0]))
		}
	}
}

func getTransactionIDFromFrame(frame []byte) uint16 {
	// Frame is encoded in BigEndian but we use LittleEndian for the value
	// since we don't bother swapping the ID value on BPF side for the map
	switch binary.BigEndian.Uint16(frame[12:14]) {
	case unix.ETH_P_IP:
		return binary.LittleEndian.Uint16(frame[42:44])
	case unix.ETH_P_IPV6:
		return binary.LittleEndian.Uint16(frame[62:64])
	}
	return 0
}

